// Vulnerable code: Using java.net.URL without proper validation can lead to SSRF (Server Side Request Forgery)
public class VulnerableExample {
    public static void main(String[] args) {
        try {
            // Vulnerable: No validation of the URL input, allowing internal server requests
            String userInput = "http://internal-api:8080/secret";
            java.net.URL url = new java.net.URL(userInput);
            java.net.HttpURLConnection connection = (java.net.HttpURLConnection) url.openConnection();
            connection.setRequestMethod("GET");
