}
***
// Fixed code: Validate the URL to prevent SSRF attacks
public class SecureExample {
    public static void main(String[] args) {
        try {
            // Secure: Validate the URL to ensure it does not point to internal resources
            String userInput = "http://internal-api:8080/secret";
            if (isValidUrl(userInput)) {
                java.net.URL url = new java.net.URL(userInput);
                java.net.HttpURLConnection connection = (java.net.HttpURLConnection) url.openConnection();
                connection.setRequestMethod("GET");
                int responseCode = connection.getResponseCode();
                System.out.println("Response Code: " + responseCode);
            } else {
                System.out.println("Invalid URL: " + userInput);
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    // Helper method to validate the URL
    private static boolean isValidUrl(String url) {
        // Simple validation: check if the URL starts with http:// or https:// and does not contain internal hosts
        if (url == null || url.isEmpty()) {
            return false;
        }
        if (!url.startsWith("http://") && !url.startsWith("https://")) {
            return false;
        }
        // Example: block internal hosts like internal-api, localhost, 127.0.0.1, etc.
        if (url.contains("internal-api") || url.contains("localhost") || url.contains("127.0.0.1")) {
            return false;
        }
        return true;
    }
}
