[extrait de code 2]
```java
// Correction : Utilisation de PreparedStatement pour prévenir les injections SQL
String userInput = request.getParameter("username");
// Vérification de la longueur et échappement des caractères spéciaux
if (userInput != null && userInput.length() <= 50) {
    String query = "SELECT * FROM users WHERE username = ?";
    PreparedStatement pstmt = connection.prepareStatement(query);
    pstmt.setString(1, userInput);
    ResultSet rs = pstmt.executeQuery();
} else {
    // Gestion de l'erreur : entrée invalide
    System.out.println("Entrée invalide");
}
```

