// 安全处理：对用户输入进行验证和转义，防止 XSS 和其他注入攻击
String userInput = request.getParameter("username");
// 验证输入是否符合预期格式（例如仅包含字母和数字）
if (userInput != null && userInput.matches("[a-zA-Z0-9]+")) {
    // 使用 HTML 转义方法确保安全输出
    String safeOutput = "<div>Welcome, " + java.net.URLEncoder.encode(userInput, "UTF-8") + "</div>";
    response.getWriter().write(safeOutput);
} else {
    response.getWriter().write("<div>Welcome, Guest</div>");
}
