public class UserService {
    public void login(String username, String password) {
        // Invio delle credenziali in chiaro su una connessione non sicura
        // Questo è un esempio di vulnerabilità di tipo "Insecure Data Transmission"
        System.out.println("Username: " + username + ", Password: " + password);
        // Simulazione di autenticazione (non sicura)
