// Corretto: utilizzo sicuro delle API Java per la gestione delle credenziali
public class UserService {
    public void login(String username, String password) {
        // Utilizzo di una connessione sicura (es. HTTPS) e crittografia delle credenziali
        // Simulazione di autenticazione (in un ambiente reale si userebbero API sicure come Spring Security)
        System.out.println("Username: " + username);
        // La password non viene stampata o inviata in chiaro
        // Si dovrebbe utilizzare un sistema di autenticazione sicuro
        if (username.equals("admin") && password.equals("password")) {
